// Type-aware lint rules for every TypeScript and JavaScript file in the
// workspace. Formatting is Prettier's job, so conflicting style rules are off.
import js from '@eslint/js';
import prettier from 'eslint-config-prettier';
import { defineConfig } from 'eslint/config';
import ts from 'typescript-eslint';

export default defineConfig(
  {
    ignores: [
      'target/',
      'test-results/',
      'playwright-report/',
      '.claude/',
      '.dev/',
      'packages/*/dist/',
      // Generated by `just sdk-types`; tsc still checks it.
      'packages/auth/src/protocol.ts'
    ]
  },
  js.configs.recommended,
  ts.configs.strictTypeChecked,
  ts.configs.stylisticTypeChecked,
  prettier,
  {
    languageOptions: {
      parserOptions: {
        // Each file uses its nearest tsconfig.json.
        projectService: true,
        tsconfigRootDir: import.meta.dirname
      }
    },
    rules: {
      // TypeScript already reports undefined identifiers, including browser and
      // Node globals, so ESLint's environment-unaware check only adds noise.
      'no-undef': 'off',
      // The codebase consistently declares object shapes as type aliases.
      '@typescript-eslint/consistent-type-definitions': ['error', 'type'],
      // node:test reports the promises `test` and `describe` return itself.
      '@typescript-eslint/no-floating-promises': [
        'error',
        {
          allowForKnownSafeCalls: [
            { from: 'package', package: 'node:test', name: ['test', 'describe'] }
          ]
        }
      ]
    }
  },
  {
    // The runtime smoke scripts import the built package, which does not exist yet
    // when linting runs, so they get the rules that need no types.
    files: ['packages/auth/test/smoke/*.js'],
    extends: [ts.configs.disableTypeChecked]
  }
);
